"""Build self-contained per-project depth inspector, frozen evidence inline.
Native JS; filter samples, compare metrics, inspect specialized diagnostics, export selections.
No local-file fetch, remote calls, or fake retraining button.
"""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1]
STYLE='''*{box-sizing:border-box}body{margin:0;font:15px/1.65 Arial,PingFang SC,Microsoft YaHei,sans-serif;color:#273646;background:#f7f9fc}main{max-width:1180px;margin:auto;padding:28px}a{color:#215c9b}header{border-bottom:1px solid #dbe3ec;padding-bottom:20px}h1{font-size:28px;line-height:1.3;margin:14px 0}h2{font-size:20px}.tag{font-size:12px;color:#64758b}.scope{font-size:13px;color:#64758b}.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}select,input,button{font:inherit;padding:8px;border:1px solid #c7d3e1;border-radius:4px;background:#fff}button{cursor:pointer}button.primary{background:#215c9b;color:white}.panel{background:#fff;border:1px solid #dbe3ec;border-radius:6px;padding:20px;margin:20px 0;overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:9px 11px;border-bottom:1px solid #e6ebf2;text-align:left;white-space:nowrap}tr[data-index]{cursor:pointer}tr[data-index]:hover{background:#edf4fd}.records{max-height:520px;overflow:auto}.json{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;line-height:1.5;font-family:monospace}#chart{width:100%;height:330px}details{margin:12px 0}summary{cursor:pointer;color:#215c9b}.stats{display:flex;gap:25px;font-size:18px}.pagination{display:flex;gap:16px;align-items:center}.warn{border-left:3px solid #b47721;padding-left:12px}input[type=search]{width:220px}@media(max-width:700px){main{padding:16px}h1{font-size:23px}.panel{padding:14px}#chart{height:280px}.toolbar>*{max-width:100%}}'''
JS=r'''
const DATA=__DATA__,$=id=>document.getElementById(id),state={condition:'all',model:'all',failure:false,search:'',page:0};const metrics=DATA.metrics,records=DATA.records;const uniq=(rows,key)=>[...new Set(rows.map(r=>r[key]))];
function addOptions(id,options){options.forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;$(id).append(o)})}addOptions('condition',uniq(records,'condition'));addOptions('model',uniq(records,'model'));addOptions('diagnostic',Object.keys(DATA.details));const metricOptions=['accuracy','mae','rmse','mean_elapsed_ms','mean_nmse','admission_coverage','nll'].filter(k=>metrics.some(r=>k in r));addOptions('metric',metricOptions);$('metric').value=DATA.title.startsWith('SpecDecode')?'mean_elapsed_ms':DATA.title.startsWith('ChannelEst')?'mean_nmse':DATA.title.startsWith('SparseMoE')?'rmse':metricOptions[0];state.condition=uniq(records,'condition')[0];$('condition').value=state.condition;$('metric').addEventListener('change',render);
function current(){return records.filter(r=>(state.condition==='all'||r.condition===state.condition)&&(state.model==='all'||r.model===state.model)&&(!state.failure||(r.correct===false||r.admitted===false||r.covered===false))&&(!state.search||JSON.stringify(r).toLowerCase().includes(state.search.toLowerCase())))}
function cell(v){const td=document.createElement('td');td.textContent=v==null?'—':typeof v==='number'?Number(v.toPrecision(5)):String(v);return td}function table(id,rows,keys,clickable=false){const t=$(id);t.replaceChildren();const tr=document.createElement('tr');keys.forEach(k=>{const th=document.createElement('th');th.textContent=k;tr.append(th)});t.append(tr);rows.forEach((r,i)=>{const tr=document.createElement('tr');keys.forEach(k=>tr.append(cell(r[k])));if(clickable){tr.dataset.index=i;tr.addEventListener('click',()=>{$('record').textContent=JSON.stringify(r,null,2)})}t.append(tr)})}
function chart(rows){const svg=$('chart');svg.replaceChildren();const ns='http://www.w3.org/2000/svg',draw=(tag,a,txt)=>{const e=document.createElementNS(ns,tag);Object.entries(a).forEach(([k,v])=>e.setAttribute(k,v));if(txt)e.textContent=txt;svg.append(e)};const key=$('metric').value;if(!key)return;rows=rows.filter(r=>r[key]!==undefined).slice(0,12);if(!rows.length)return;const max=Math.max(...rows.map(r=>r[key]),.01)*(key==='accuracy'?1.1:1.2);const width=1000,height=300;svg.setAttribute('viewBox','0 0 1000 340');for(let i=0;i<=4;i++){let y=height-40-(height-80)*i/4;draw('line',{x1:55,y1:y,x2:975,y2:y,stroke:'#e4eaf2'});draw('text',{x:8,y:y+5,fill:'#64758b','font-size':14},(max*i/4).toFixed(2))}let w=900/rows.length;rows.forEach((r,i)=>{let h=(height-80)*r[key]/max,x=55+i*w;draw('rect',{x:x+8,y:height-40-h,width:Math.max(8,w-16),height:h,fill:i%2?'#829cbb':'#215c9b'});draw('text',{x:x+w/2,y:height-46-h,'text-anchor':'middle','font-size':13,fill:'#273646'},r[key].toFixed(3));draw('text',{x:x+w/2,y:height-22,'text-anchor':'middle','font-size':12,fill:'#64758b'},r.model.slice(0,15))});draw('text',{x:55,y:325,fill:'#64758b','font-size':12},key+' · 前12组；完整数字见表。Accuracy在部分项目代表明确定义的成功/一致性，不是模型总准确率。')}
function render(){const rr=current(),mm=metrics.filter(r=>(state.condition==='all'||r.condition===state.condition)&&(state.model==='all'||r.model===state.model));$('count').textContent=rr.length+' / '+records.length+' 条记录';$('page').textContent=(state.page+1)+' / '+Math.max(1,Math.ceil(rr.length/50));table('metrics',mm,uniq([].concat(...mm.map(r=>Object.keys(r).map(k=>({k})))),'k').filter(k=>k!=='accuracy_interval'));const shown=rr.slice(state.page*50,state.page*50+50),keys=['model','condition','index','truth','prediction','correct','error','confidence','elapsed_ms'].filter(k=>shown.some(r=>k in r));table('rows',shown,keys,true);chart(mm)}
['condition','model'].forEach(id=>$(id).addEventListener('change',e=>{state[id]=e.target.value;state.page=0;render()}));$('failure').addEventListener('change',e=>{state.failure=e.target.checked;state.page=0;render()});$('search').addEventListener('input',e=>{state.search=e.target.value;state.page=0;render()});$('prev').addEventListener('click',()=>{state.page=Math.max(0,state.page-1);render()});$('next').addEventListener('click',()=>{if((state.page+1)*50<current().length)state.page++;render()});$('export').addEventListener('click',()=>{const b=new Blob([JSON.stringify({title:DATA.title,protocol:DATA.protocol,selection:state,records:current(),source_hashes:DATA.source_hashes},null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='depth-selection.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});$('diagnostic').addEventListener('change',()=>{$('details-data').textContent=JSON.stringify(DATA.details[$('diagnostic').value],null,2)});$('details-data').textContent=JSON.stringify(DATA.details[Object.keys(DATA.details)[0]],null,2);$('protocol').textContent=DATA.protocol;$('environment').textContent=JSON.stringify({environment:DATA.environment,source_hashes:DATA.source_hashes},null,2);DATA.findings.forEach(t=>{const li=document.createElement('li');li.textContent=t;$('findings').append(li)});render();
'''
def build():
    for result in sorted(ROOT.glob('projects/*/artifacts/depth/results.json')):
        d=json.loads(result.read_text());project=result.parents[2];payload=json.dumps(d,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
        page='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(d['title'])+'</title><style>'+STYLE+'</style></head><body><main><header><a href="../../index.html#experiments">返回作品集</a> · <a href="demo.html">原模型Demo</a> · <a href="artifacts/depth/REPORT.md">深化报告</a><div class="tag">DEPTH STUDY · AI-ASSISTED · READ-ONLY LOCAL EVIDENCE</div><h1>'+html.escape(d['title'])+'</h1><p id="protocol"></p><p class="scope warn">新旧结果分开。这里分析实际记录，不在浏览器重训，不调用真实大模型或设备。阈值/条件筛选用于探索，不作为未见数据上的安全保证。</p></header><div class="toolbar"><select id="condition" aria-label="实验条件"><option value="all">全部条件</option></select><select id="model" aria-label="模型策略"><option value="all">全部模型</option></select><label><input id="failure" type="checkbox"> 只看失败 / 丢弃 / 未覆盖</label><input id="search" type="search" placeholder="检索记录字段" aria-label="搜索记录"><button id="export" class="primary">导出当前证据</button></div><div class="stats"><strong id="count"></strong></div><section class="panel"><h2>对照与实测</h2><label>图表指标 <select id="metric" aria-label="图表指标"></select></label><svg id="chart" role="img" aria-label="条件对照图"></svg><table id="metrics"></table></section><section class="panel"><h2>逐条证据与失败定位</h2><div class="records"><table id="rows"></table></div><div class="pagination"><button id="prev">上一页</button><span id="page"></span><button id="next">下一页</button></div><details open><summary>点击任一记录查看完整证据</summary><pre id="record" class="json">尚未选择记录</pre></details></section><section class="panel"><h2>项目专属诊断</h2><select id="diagnostic" aria-label="专属诊断"></select><details open><summary>诊断结果、曲线与轨迹</summary><pre id="details-data" class="json"></pre></details></section><section class="panel"><h2>发现与边界</h2><ul id="findings"></ul><details><summary>环境与源码哈希</summary><pre id="environment" class="json"></pre></details></section></main><script>'+JS.replace('__DATA__',payload)+'</script></body></html>'
        (project/'depth-demo.html').write_text(page);print(project.name,len(page),'chars')
if __name__=='__main__':build()
